import { Checkbox } from "march/ui"
import { sparkles } from "march/icons"

// tatil bavulu: her eşyayı işaretledikçe sayaç dolar; hepsi hazır olunca yola çıkma vakti
const items = ["Pasaport", "Güneş kremi", "Mayo", "Şarj aleti", "Kitap", "Gözlük"]

export function PackingList() {
  let $packed: string[] = []
  const toggle = (item: string, on: boolean) => $packed = on ? [...$packed, item] : $packed.filter((x) => x !== item)
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      {items.map((item) => <Checkbox variant="chip" label={item} value={$packed.includes(item)} onChange={(on) => toggle(item, on)} />)}
    </div>
    <span sx={{ text: "bold", color: $packed.length === items.length ? "brand-green" : "muted" }}>
      {$packed.length === items.length ? "Bavul hazır, iyi yolculuklar!" : `${$packed.length} / ${items.length} eşya bavulda`}
    </span>
    <Checkbox icon={sparkles} m:color="brand-gold" label="Bavulu tamamen hazırla" value={$packed.length === items.length}
      indeterminate={$packed.length > 0 && $packed.length < items.length} onChange={(on) => $packed = on ? [...items] : []} />
  </div>
}

import { Checkbox, Card, Button, toast } from "march/ui"
import { bell, mail, message, megaphone } from "march/icons"

// profil ayarları: bildirim kanalları (toggle), üstte "tümü" kutusu kısmi durumu gösterir, en altta kaydet
const channels = [
  { id: "push", label: "Anlık bildirimler", hint: "Telefonda ve tarayıcıda", icon: bell },
  { id: "mail", label: "E-posta özeti", hint: "Her pazartesi sabahı", icon: mail },
  { id: "dm", label: "Doğrudan mesajlar", hint: "Biri sana yazınca", icon: message },
  { id: "news", label: "Duyurular", hint: "Yeni özellikler ve kampanyalar", icon: megaphone },
]

export function NotificationSettings() {
  let $on = ["push", "dm"]
  const set = (id: string, v: boolean) => $on = v ? [...$on, id] : $on.filter((x) => x !== id)
  return <Card>
    <div sx={{ flex: "col", gap: 3 }}>
      <Checkbox label="Bütün bildirimler" size="lg" value={$on.length === channels.length}
        indeterminate={$on.length > 0 && $on.length < channels.length} onChange={(v) => $on = v ? channels.map((c) => c.id) : []} />
      {channels.map((c) => <Checkbox variant="card" icon={c.icon} label={c.label} hint={c.hint}
        value={$on.includes(c.id)} onChange={(v) => set(c.id, v)} />)}
      <Checkbox variant="toggle" label="Gece 23.00 ile 08.00 arası sessiz" value={true} />
      <div sx={{ flex: ["row", "end"] }}>
        <Button variant="primary" on:click={() => toast(`${$on.length} kanal kaydedildi`)}>Kaydet</Button>
      </div>
    </div>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { CheckboxLab } from "./CheckboxLab.tsx"

// CheckboxLab'in testleri: kaydedince Testler sekmesinde çalışır
// bir etiketin kutusu: etiketin metninden <input>'a
const boxOf = (el: Element | null) => el?.closest("label")?.querySelector("input") as HTMLInputElement

test("Koşullara basınca değer ve onChange birlikte değişir", async () => {
  const s = renderTest(() => <CheckboxLab />)
  expect(s.text().includes("Onay: hayır")).toBe(true)
  await s.click("Koşulları kabul ediyorum")
  expect(s.text().includes("Onay: evet · son: işaretlendi")).toBe(true)
  await s.click("Koşulları kabul ediyorum")
  expect(s.text().includes("Onay: hayır · son: kaldırıldı")).toBe(true)
})

test("devre dışı ve salt okunur kutular tıklanamaz; zorunlu ve geçersiz aria ile söylenir", () => {
  const s = renderTest(() => <CheckboxLab />)
  expect(boxOf(s.find("Devre dışı")).disabled).toBe(true)
  expect(boxOf(s.find("Salt okunur")).disabled).toBe(true)
  expect(boxOf(s.find("Koşulları kabul ediyorum")).required).toBe(true)
  const kvkk = boxOf(s.find("KVKK metnini okudum"))
  expect(kvkk.getAttribute("aria-invalid")).toBe("true")
  expect(kvkk.getAttribute("aria-describedby")).toBe("kvkk-error")
})

test("kısmi durum kutuya indeterminate olarak geçer", () => {
  const s = renderTest(() => <CheckboxLab />)
  expect(boxOf(s.find("Bazı dosyalar seçili")).indeterminate).toBe(true)
  expect(boxOf(s.find("Animasyonsuz")).checked).toBe(false)
})

test("etiketsiz kutu aria-label ile bulunur; id, name, class ve onClick ona gider", async () => {
  const s = renderTest(() => <CheckboxLab />)
  const row = s.find("Satırı seç") as HTMLInputElement
  expect(row.tagName).toBe("INPUT")
  expect(row.id).toBe("row-1")
  expect(row.name).toBe("rows")
  expect(row.closest(".lab-row") !== null).toBe(true)
  await s.click(row)
  expect(row.checked).toBe(true)
  expect(s.text().includes("Tıklama: 1")).toBe(true)
})
